package com.example.blades360;
import android.app.*;
import android.content.*;
import android.graphics.*;
import android.os.Bundle;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

public final class YoutubeInstrumentation extends Instrumentation {
 int checks;MainActivity a;YoutubeClient original,client;YoutubeBrowser browser;
 void check(boolean ok,String label){checks++;if(!ok)throw new AssertionError(label);}
 void ui(Runnable run){runOnMainSync(run);}
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle output=new Bundle();a=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));try{
  check(!YoutubeClient.input("https://www.youtube.com/watch?v=BaW_jenozKc").isEmpty(),"YouTube URL allowed");check(YoutubeClient.input("https://youtube.com.evil.invalid/watch").isEmpty(),"Lookalike domain rejected");check(YoutubeClient.input("file:///sdcard/test").isEmpty(),"Local input rejected");check(YoutubeClient.input("https://user@youtube.com/watch").isEmpty(),"User-info rejected");
  ui(()->{if(a.bootAnimation!=null)a.bootAnimation.finish();original=a.youtube;client=new YoutubeClient(a,"youtube_test");a.youtube=client;a.openJellyfin();check(a.jellyfinBrowser.rows.size()==4,"Four media services");a.jellyfinBrowser.close();a.openYoutube();browser=a.youtubeBrowser;check(browser.rows.size()>=8,"YouTube home sections");});
  JSONObject fixture=new JSONObject().put("id","BaW_jenozKc").put("title","Test video").put("channel","Test channel").put("channel_id","UCxxxxxxxxxxxxxxxxxxxxxx").put("url",YoutubeClient.watch("BaW_jenozKc"));ui(()->{client.toggle("later",fixture);check(client.contains("later","BaW_jenozKc"),"Watch Later saves");client.toggle("later",fixture);check(!client.contains("later","BaW_jenozKc"),"Watch Later removes");client.toggle("likes",fixture);check(client.list("likes").length()==1,"Local favorite");client.subscription(fixture);check(client.list("subscriptions").length()==1,"Local subscription");client.subscription(fixture);check(client.list("subscriptions").length()==0,"Local unsubscribe");client.history(fixture,12345);check(client.position("BaW_jenozKc")==12345,"Resume position");client.enqueue(fixture);client.enqueue(fixture);check(client.popQueue()!=null&&client.list("queue").length()==1,"Queue order and consume");client.enqueue(fixture);client.removeQueued(fixture.optString("id"));check(client.list("queue").length()==1,"Selected queue video consumes only one occurrence");});
  client.ensure();String version=client.execute(client.request("https://www.youtube.com").addOption("--version"),client.generation).trim();check(version.equals(YoutubeClient.BUNDLED),"Bundled latest yt-dlp executes: "+version);
  CountDownLatch searched=new CountDownLatch(1);JSONArray[] found={null};ui(()->client.browse("search:yt-dlp test video",0,rows->{found[0]=rows;searched.countDown();}));boolean searchDone=searched.await(80,TimeUnit.SECONDS);check(searchDone&&found[0]!=null&&found[0].length()>0,"Live search: "+client.status);
  ui(()->{browser.entries=found[0];browser.listSource="search:yt-dlp test video";browser.listTitle="Search: yt-dlp test video";browser.page(1);});waitForIdleSync();Thread.sleep(500);Bitmap screen=getUiAutomation().takeScreenshot();if(screen!=null){try(FileOutputStream out=new FileOutputStream(new File(a.getExternalFilesDir(null),"youtube-search-test.png"))){screen.compress(Bitmap.CompressFormat.PNG,100,out);}screen.recycle();}
  CountDownLatch resolved=new CountDownLatch(1);JSONObject[] info={null};ui(()->client.resolve(found[0].optJSONObject(0),false,data->{info[0]=data;resolved.countDown();}));check(resolved.await(80,TimeUnit.SECONDS)&&info[0]!=null,"Live extraction: "+client.status);check(info[0].has("url")||info[0].has("requested_formats"),"Playable streams returned");
  ui(()->{browser.player=new YoutubePlayer(browser,info[0],0);a.addContentView(browser.player,new android.view.ViewGroup.LayoutParams(-1,-1));browser.player.requestFocus();});boolean[] ready={false};for(int i=0;i<60;i++){ui(()->ready[0]=browser.player.prepared);if(ready[0])break;Thread.sleep(500);}check(ready[0],"Live YouTube playback prepares");ui(()->{check(browser.player.engine.getCurrentTracks().getGroups().size()>0,"Playback tracks present");browser.player.showOptions();check(browser.player.options.size()>=10,"Blades playback options");browser.player.pause();check(!browser.player.engine.getPlayWhenReady(),"Playback pauses");browser.player.close();check(browser.player==null,"Player cleanup");});
  JSONObject resolvedVideo=YoutubeClient.compact(info[0]);check(!resolvedVideo.optString("channel_url").isEmpty(),"Canonical channel resolved");CountDownLatch feedReady=new CountDownLatch(1);JSONArray[] feed={null};ui(()->{client.subscription(resolvedVideo);client.feed(rows->{feed[0]=rows;feedReady.countDown();});});check(feedReady.await(45,TimeUnit.SECONDS)&&feed[0]!=null&&feed[0].length()>0,"Live subscription RSS feed: "+client.status);CountDownLatch channelReady=new CountDownLatch(1);JSONArray[] uploads={null};ui(()->client.browse(resolvedVideo.optString("channel_url")+"/videos",0,rows->{uploads[0]=rows;channelReady.countDown();}));check(channelReady.await(80,TimeUnit.SECONDS)&&uploads[0]!=null&&uploads[0].length()>0,"Live channel browsing: "+client.status);output.putString("stream","PASS: "+checks+" YouTube checks");
 }catch(Throwable e){output.putString("stream","FAIL: "+e.getClass().getSimpleName()+": "+e.getMessage());}finally{ui(()->{if(browser!=null&&!browser.closed)browser.close();if(a.jellyfinBrowser!=null)a.jellyfinBrowser.close();if(client!=null){client.close();client.prefs.edit().clear().commit();}if(original!=null)a.youtube=original;});}finish(output.getString("stream").startsWith("PASS")?Activity.RESULT_OK:Activity.RESULT_CANCELED,output);}
}
